files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #000000;
  --vt-accent-ink: #c12828;
  --vt-accent-on-deep: #d6a354;
  --vt-line: #e0e0e0;
  font-family: 'Unbounded', sans-serif;
  background-color: var(--vt-surface);
  color: var(--vt-ink);
  min-height: 100vh;
  position: relative;
}

.root * {
  box-sizing: border-box;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 2px;
}

/* Sidebar */
.root .sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 25%;
  background: var(--vt-accent);
  z-index: 100;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 50px 0;
  overflow-y: auto;
  transition: transform 0.3s ease;
}

.root .sidebarInner {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}

.root .logo {
  display: block;
  margin-bottom: 70px;
}

.root .brand {
  width: 154px;
}

.root .nav {
  width: 100%;
}

.root .navList {
  list-style: none;
  padding: 0;
  margin: 0;
  text-align: center;
}

.root .navItem {
  margin-bottom: 20px;
}

.root .navLink {
  color: var(--vt-on-accent);
  font-size: 1.25rem;
  font-weight: bold;
  text-transform: uppercase;
  text-decoration: none;
  transition: color 0.3s;
}

.root .navLink:hover,
.root .navLink:focus {
  color: var(--vt-surface);
}

/* Mobile toggle */
.root .sidebarToggle {
  display: none;
}

.root .sidebarToggleLabel {
  display: none;
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 200;
  background: var(--vt-accent);
  border-radius: 50%;
  width: 55px;
  height: 55px;
  cursor: pointer;
  align-items: center;
  justify-content: center;
}

.root .sidebarToggleIcon,
.root .sidebarToggleIcon::before,
.root .sidebarToggleIcon::after {
  display: block;
  background: var(--vt-on-accent);
  width: 25px;
  height: 2px;
  position: relative;
  transition: all 0.3s;
}

.root .sidebarToggleIcon::before,
.root .sidebarToggleIcon::after {
  content: '';
  position: absolute;
  left: 0;
}

.root .sidebarToggleIcon::before {
  top: -8px;
}

.root .sidebarToggleIcon::after {
  top: 8px;
}

.root .sidebarToggle:checked ~ .sidebar {
  transform: translateX(0);
}

/* Main */
.root .main {
  margin-left: 25%;
  width: 75%;
  min-height: 100vh;
}

/* Sections */
.root .section {
  padding: 100px 50px;
}

.root .container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
}

/* Hero */
.root .hero {
  position: relative;
  min-height: 665px;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  border-bottom: 15px solid var(--vt-accent);
  display: flex;
  align-items: center;
  overflow: hidden;
}

.root .heroOverlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #FDBB2D 0%, #22C1C3 100%);
  opacity: 0.65;
  z-index: 1;
}

.root .heroContent {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 0 50px;
  margin: 0 auto;
}

.root .heroTitle {
  font-size: 4rem;
  color: var(--vt-on-deep);
  margin-bottom: 20px;
}

.root .heroTitle em {
  font-style: italic;
  color: var(--vt-accent);
}

.root .heroTagline {
  color: var(--vt-ink);
  font-size: 1.5rem;
  margin-bottom: 40px;
}

.root .heroButtons {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}

.root .btn {
  padding: 10px 20px;
  border-radius: 50px;
  font-size: 1rem;
  font-weight: bold;
  text-decoration: none;
  transition: all 0.3s;
  border: 2px solid transparent;
}

.root .btnPrimary {
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
}

.root .btnPrimary:hover {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.root .btnOutline {
  background: transparent;
  border-color: var(--vt-accent-ink);
  color: var(--vt-accent-ink);
}

.root .btnOutline:hover {
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
}

/* Story */
.root .storyGrid {
  display: flex;
  gap: 50px;
  align-items: center;
}

.root .storyImageWrap {
  flex: 1;
  max-width: 500px;
}

.root .storyImage {
  width: 100%;
  height: auto;
  border-radius: 20px;
  transform: rotate(3deg);
  transition: transform 0.3s;
}

.root .storyImageWrap:hover .storyImage {
  transform: rotate(0deg) scale(1.02);
}

.root .storyContent {
  flex: 1;
}

.root .sectionTitle {
  font-size: 2.5rem;
  margin-bottom: 30px;
  color: var(--vt-ink);
}

.root .storyParagraph {
  color: var(--vt-ink-soft);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 20px;
}

/* Services */
.root .servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 30px;
}

.root .serviceCard {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  background: var(--vt-surface-2);
}

.root .serviceImage {
  width: 100%;
  height: 300px;
  object-fit: cover;
  transition: transform 0.3s;
}

.root .serviceCard:hover .serviceImage {
  transform: scale(1.05);
}

.root .serviceInfo {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 20px;
  background: linear-gradient(to top, rgba(0,0,0,0.7), transparent);
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 10px;
}

.root .serviceTitle {
  color: var(--vt-on-deep);
  font-size: 1.5rem;
  margin: 0;
  flex: 1;
}

.root .serviceDesc {
  color: var(--vt-on-deep);
  font-size: 0.9rem;
  width: 100%;
}

.root .serviceDuration {
  color: var(--vt-on-deep);
  font-size: 0.9rem;
}

.root .servicePrice {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 20px;
  padding: 5px 15px;
  font-weight: bold;
}

/* Price List */
.root .priceListSection {
  background: var(--vt-surface-2);
}

.root .priceListGrid {
  display: flex;
  gap: 50px;
  align-items: center;
}

.root .priceListContent {
  flex: 2;
}

.root .priceList {
  list-style: none;
  padding: 0;
}

.root .priceItem {
  display: flex;
  align-items: baseline;
  margin-bottom: 15px;
}

.root .priceName {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--vt-ink);
  white-space: nowrap;
}

.root .priceDivider {
  flex: 1;
  height: 2px;
  background: var(--vt-ink-soft);
  margin: 0 15px;
  align-self: center;
}

.root .priceValue {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--vt-accent-ink);
  white-space: nowrap;
}

.root .priceListImageWrap {
  flex: 1;
  max-width: 400px;
  padding: 0;
  margin: 0;
  box-sizing: border-box;
  overflow: hidden;
}

.root .priceListImage {
  width: 100%;
  height: auto;
  border-radius: 20px;
  transition: transform 0.3s;
}

.root .priceListImageWrap:hover .priceListImage {
  transform: scale(1.05);
}

/* Contact */
.root .contactGrid {
  display: flex;
  gap: 50px;
  align-items: flex-start;
}

.root .contactInfo {
  flex: 1;
}

.root .contactBlockWrap {
  flex: 1;
  max-width: 400px;
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 0;
  margin: 0;
  box-sizing: border-box;
  overflow: hidden;
}

.root .contactBlock {
  background: var(--vt-accent-ink);
  border-radius: 20px;
  transform: rotate(5deg);
  padding: 30px;
  text-align: center;
  height: 100%;
}

.root .contactBlockTitle {
  color: var(--vt-on-deep);
  font-size: 1.8rem;
  margin-bottom: 15px;
}

.root .contactBlockHours {
  color: var(--vt-on-deep);
  font-size: 1.2rem;
}

.root .areasSection {
  margin-top: 80px;
}

.root .areasTitle {
  font-size: 1.8rem;
  margin-bottom: 15px;
  color: var(--vt-ink);
}

.root .areasText {
  color: var(--vt-ink-soft);
  font-size: 1.1rem;
  line-height: 1.8;
}

/* Footer */
.root .footer {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  text-align: center;
  padding: 30px 50px;
  position: relative;
}

.root .footer::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 10px;
  background: linear-gradient(90deg, #FDBB2D 0%, #22C1C3 100%);
}

.root .copyright {
  margin: 0;
  color: var(--vt-on-deep);
  font-size: 0.9rem;
}

/* Responsive */
@media screen and (max-width: 991px) {
  .root .sidebar {
    transform: translateX(-100%);
    width: 280px;
    transition: transform 0.3s ease;
  }

  .root .sidebarToggleLabel {
    display: flex;
  }

  .root .main {
    margin-left: 0;
    width: 100%;
  }

  .root .section {
    padding: 80px 25px;
  }

  .root .hero {
    min-height: 500px;
  }

  .root .heroContent {
    padding: 0 25px;
  }

  .root .heroTitle {
    font-size: 3rem;
  }

  .root .storyGrid,
  .root .priceListGrid,
  .root .contactGrid {
    flex-direction: column;
  }

  .root .servicesGrid {
    grid-template-columns: 1fr;
  }

  .root .priceListImageWrap,
  .root .contactBlockWrap {
    max-width: 100%;
  }
}

@media screen and (max-width: 767px) {
  .root .heroTitle {
    font-size: 2rem;
  }

  .root .heroTagline {
    font-size: 1.1rem;
  }

  .root .sectionTitle {
    font-size: 2rem;
  }

  .root .btn {
    padding: 8px 16px;
    font-size: 0.9rem;
  }
}

@media screen and (max-width: 480px) {
  .root .heroTitle {
    font-size: 1.8rem;
  }

  .root .sectionTitle {
    font-size: 1.6rem;
  }

  .root .serviceInfo {
    padding: 10px;
  }

  .root .serviceTitle {
    font-size: 1.2rem;
  }

  .root .priceName,
  .root .priceValue {
    font-size: 1rem;
  }
}
